{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "CP-96,345, which shares the 2-methoxybenzylamine and basic amine motif with the query, showed minimal brain uptake in guinea pigs (≈0.1% of injected dose) and was concluded to be excluded by the BBB, likely due to its cationic form.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A tryptophan-derived radiotracer with the same indole side chain showed low brain uptake (0.84 %ID/g) in mice, indicating that the tryptophan/indole scaffold does not ensure CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Carfilzomib, a high-molecular-weight peptide-like compound with multiple amides, did not suppress brain CT-L activity after IV dosing in rats, demonstrating poor BBB permeability for this peptidomimetic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "CI988, a tryptophan-containing dipeptoid, was undetectable in rat brain after IV administration after correcting for residual plasma, supporting poor brain penetrability for tryptophan/peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Another tryptophan analogue, [18F]FPOTrp, also showed low brain uptake (1.16 %ID/g) in mice, reinforcing the pattern of poor CNS access for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a high-MW, basic, peptidomimetic tryptophan derivative. The most transferable direct in vivo evidence—CP-96,345, tryptophan radiotracers, carfilzomib, and CI988—consistently shows poor BBB penetration. Low-transfer permeable analogues do not outweigh this consistent pattern, so the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter phenotype of the query was not directly measured.",
    "Possible active uptake or prodrug behavior was not experimentally assessed.",
    "Human CNS exposure data are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

